dfp_read_field_def_Message(<<>>, 0, 0, _, F@_1, F@_2, R1, F@_4, TrUserData) ->
    S1 = #{role => F@_1, content => F@_2, tool_call_id => F@_4},
    if R1 == '$undef' -> S1;
       true -> S1#{tool_calls => lists_reverse(R1, TrUserData)}
    end;
