skip_length_delimited_AgentRequest(<<1:1, X:7, Rest/binary>>, N, Acc, F, F@_1, TrUserData) when N < 57 -> skip_length_delimited_AgentRequest(Rest, N + 7, X bsl N + Acc, F, F@_1, TrUserData);
skip_length_delimited_AgentRequest(<<0:1, X:7, Rest/binary>>, N, Acc, F, F@_1, TrUserData) ->
    Length = X bsl N + Acc,
    <<_:Length/binary, Rest2/binary>> = Rest,
    dfp_read_field_def_AgentRequest(Rest2, 0, 0, F, F@_1, TrUserData).

skip_group_AgentRequest(Bin, _, Z2, FNum, F@_1, TrUserData) ->
    {_, Rest} = read_group(Bin, FNum),
    dfp_read_field_def_AgentRequest(Rest, 0, Z2, FNum, F@_1, TrUserData).

skip_32_AgentRequest(<<_:32, Rest/binary>>, Z1, Z2, F, F@_1, TrUserData) -> dfp_read_field_def_AgentRequest(Rest, Z1, Z2, F, F@_1, TrUserData).

skip_64_AgentRequest(<<_:64, Rest/binary>>, Z1, Z2, F, F@_1, TrUserData) -> dfp_read_field_def_AgentRequest(Rest, Z1, Z2, F, F@_1, TrUserData).

decode_msg_AgentResponse(Bin, TrUserData) -> dfp_read_field_def_AgentResponse(Bin, 0, 0, 0, id('$undef', TrUserData), TrUserData).

dfp_read_field_def_AgentResponse(<<10, Rest/binary>>, Z1, Z2, F, F@_1, TrUserData) -> d_field_AgentResponse_llm_infer(Rest, Z1, Z2, F, F@_1, TrUserData);
dfp_read_field_def_AgentResponse(<<18, Rest/binary>>, Z1, Z2, F, F@_1, TrUserData) -> d_field_AgentResponse_tool_exec(Rest, Z1, Z2, F, F@_1, TrUserData);
dfp_read_field_def_AgentResponse(<<>>, 0, 0, _, F@_1, _) ->
    S1 = #{},
    if F@_1 == '$undef' -> S1;
       true ->
           {Tagpayload, Valuepayload} = F@_1,
           S1#{Tagpayload => Valuepayload}
    end;
dfp_read_field_def_AgentResponse(Other, Z1, Z2, F, F@_1, TrUserData) -> dg_read_field_def_AgentResponse(Other, Z1, Z2, F, F@_1, TrUserData).

dg_read_field_def_AgentResponse(<<1:1, X:7, Rest/binary>>, N, Acc, F, F@_1, TrUserData) when N < 32 - 7 -> dg_read_field_def_AgentResponse(Rest, N + 7, X bsl N + Acc, F, F@_1, TrUserData);
dg_read_field_def_AgentResponse(<<0:1, X:7, Rest/binary>>, N, Acc, _, F@_1, TrUserData) ->
    Key = X bsl N + Acc,
    case Key of
        10 -> d_field_AgentResponse_llm_infer(Rest, 0, 0, 0, F@_1, TrUserData);
        18 -> d_field_AgentResponse_tool_exec(Rest, 0, 0, 0, F@_1, TrUserData);
        _ ->
            case Key band 7 of
                0 -> skip_varint_AgentResponse(Rest, 0, 0, Key bsr 3, F@_1, TrUserData);
                1 -> skip_64_AgentResponse(Rest, 0, 0, Key bsr 3, F@_1, TrUserData);
                2 -> skip_length_delimited_AgentResponse(Rest, 0, 0, Key bsr 3, F@_1, TrUserData);
                3 -> skip_group_AgentResponse(Rest, 0, 0, Key bsr 3, F@_1, TrUserData);
                5 -> skip_32_AgentResponse(Rest, 0, 0, Key bsr 3, F@_1, TrUserData)
            end
    end;
dg_read_field_def_AgentResponse(<<>>, 0, 0, _, F@_1, _) ->
    S1 = #{},
    if F@_1 == '$undef' -> S1;
       true ->
           {Tagpayload, Valuepayload} = F@_1,
           S1#{Tagpayload => Valuepayload}
    end.

d_field_AgentResponse_llm_infer(<<1:1, X:7, Rest/binary>>, N, Acc, F, F@_1, TrUserData) when N < 57 -> d_field_AgentResponse_llm_infer(Rest, N + 7, X bsl N + Acc, F, F@_1, TrUserData);
d_field_AgentResponse_llm_infer(<<0:1, X:7, Rest/binary>>, N, Acc, F, Prev, TrUserData) ->
    {NewFValue, RestF} = begin Len = X bsl N + Acc, <<Bs:Len/binary, Rest2/binary>> = Rest, {id(decode_msg_LLMInferResponse(Bs, TrUserData), TrUserData), Rest2} end,
    dfp_read_field_def_AgentResponse(RestF,
                                     0,
                                     0,
                                     F,
                                     case Prev of
                                         '$undef' -> id({llm_infer, NewFValue}, TrUserData);
                                         {llm_infer, MVPrev} -> id({llm_infer, merge_msg_LLMInferResponse(MVPrev, NewFValue, TrUserData)}, TrUserData);
                                         _ -> id({llm_infer, NewFValue}, TrUserData)
                                     end,
                                     TrUserData).

d_field_AgentResponse_tool_exec(<<1:1, X:7, Rest/binary>>, N, Acc, F, F@_1, TrUserData) when N < 57 -> d_field_AgentResponse_tool_exec(Rest, N + 7, X bsl N + Acc, F, F@_1, TrUserData);
d_field_AgentResponse_tool_exec(<<0:1, X:7, Rest/binary>>, N, Acc, F, Prev, TrUserData) ->
    {NewFValue, RestF} = begin Len = X bsl N + Acc, <<Bs:Len/binary, Rest2/binary>> = Rest, {id(decode_msg_ToolExecResponse(Bs, TrUserData), TrUserData), Rest2} end,
    dfp_read_field_def_AgentResponse(RestF,
                                     0,
                                     0,
                                     F,
                                     case Prev of
                                         '$undef' -> id({tool_exec, NewFValue}, TrUserData);
                                         {tool_exec, MVPrev} -> id({tool_exec, merge_msg_ToolExecResponse(MVPrev, NewFValue, TrUserData)}, TrUserData);
                                         _ -> id({tool_exec, NewFValue}, TrUserData)
                                     end,
                                     TrUserData).

