merge_msg_LLMInferRequest(PMsg, NMsg, TrUserData) ->
    S1 = #{},
    S2 = case {PMsg, NMsg} of
             {_, #{model := NFmodel}} -> S1#{model => NFmodel};
             {#{model := PFmodel}, _} -> S1#{model => PFmodel};
             _ -> S1
         end,
    S3 = case {PMsg, NMsg} of
             {_, #{api_base := NFapi_base}} -> S2#{api_base => NFapi_base};
             {#{api_base := PFapi_base}, _} -> S2#{api_base => PFapi_base};
             _ -> S2
         end,
    S4 = case {PMsg, NMsg} of
             {_, #{api_key := NFapi_key}} -> S3#{api_key => NFapi_key};
             {#{api_key := PFapi_key}, _} -> S3#{api_key => PFapi_key};
             _ -> S3
         end,
    S5 = case {PMsg, NMsg} of
             {#{messages := PFmessages}, #{messages := NFmessages}} -> S4#{messages => 'erlang_++'(PFmessages, NFmessages, TrUserData)};
             {_, #{messages := NFmessages}} -> S4#{messages => NFmessages};
             {#{messages := PFmessages}, _} -> S4#{messages => PFmessages};
             {_, _} -> S4
         end,
    case {PMsg, NMsg} of
        {#{tools := PFtools}, #{tools := NFtools}} -> S5#{tools => 'erlang_++'(PFtools, NFtools, TrUserData)};
        {_, #{tools := NFtools}} -> S5#{tools => NFtools};
        {#{tools := PFtools}, _} -> S5#{tools => PFtools};
        {_, _} -> S5
    end.

