verify_msg(Msg, MsgName) when is_atom(MsgName) -> verify_msg(Msg, MsgName, []).

verify_msg(Msg, MsgName, Opts) ->
    TrUserData = proplists:get_value(user_data, Opts),
    case MsgName of
        'Message' -> v_msg_Message(Msg, [MsgName], TrUserData);
        'ToolCall' -> v_msg_ToolCall(Msg, [MsgName], TrUserData);
        'ToolDesc' -> v_msg_ToolDesc(Msg, [MsgName], TrUserData);
        'LLMInferRequest' -> v_msg_LLMInferRequest(Msg, [MsgName], TrUserData);
        'LLMInferResponse' -> v_msg_LLMInferResponse(Msg, [MsgName], TrUserData);
        'ToolExecRequest' -> v_msg_ToolExecRequest(Msg, [MsgName], TrUserData);
        'ToolExecResponse' -> v_msg_ToolExecResponse(Msg, [MsgName], TrUserData);
        'AgentRequest' -> v_msg_AgentRequest(Msg, [MsgName], TrUserData);
        'AgentResponse' -> v_msg_AgentResponse(Msg, [MsgName], TrUserData);
        _ -> mk_type_error(not_a_known_message, Msg, [])
    end.


-compile({nowarn_unused_function,v_submsg_Message/3}).
-dialyzer({nowarn_function,v_submsg_Message/3}).
v_submsg_Message(Msg, Path, TrUserData) -> v_msg_Message(Msg, Path, TrUserData).

-compile({nowarn_unused_function,v_msg_Message/3}).
-dialyzer({nowarn_function,v_msg_Message/3}).
v_msg_Message(#{} = M, Path, TrUserData) ->
    case M of
        #{role := F1} -> v_type_string(F1, [role | Path], TrUserData);
        _ -> ok
    end,
    case M of
        #{content := F2} -> v_type_string(F2, [content | Path], TrUserData);
        _ -> ok
    end,
    case M of
        #{tool_calls := F3} ->
            if is_list(F3) ->
                   _ = [v_submsg_ToolCall(Elem, [tool_calls | Path], TrUserData) || Elem <- F3],
                   ok;
               true -> mk_type_error({invalid_list_of, {msg, 'ToolCall'}}, F3, [tool_calls | Path])
            end;
        _ -> ok
    end,
    case M of
        #{tool_call_id := F4} -> v_type_string(F4, [tool_call_id | Path], TrUserData);
        _ -> ok
    end,
    lists:foreach(fun (tool_call_id) -> ok;
                      (tool_calls) -> ok;
                      (content) -> ok;
                      (role) -> ok;
                      (OtherKey) -> mk_type_error({extraneous_key, OtherKey}, M, Path)
                  end,
                  maps:keys(M)),
    ok;
v_msg_Message(M, Path, _TrUserData) when is_map(M) -> mk_type_error({missing_fields, [] -- maps:keys(M), 'Message'}, M, Path);
v_msg_Message(X, Path, _TrUserData) -> mk_type_error({expected_msg, 'Message'}, X, Path).

-compile({nowarn_unused_function,v_submsg_ToolCall/3}).
-dialyzer({nowarn_function,v_submsg_ToolCall/3}).
