fqbin_to_msg_name(<<"hermes.ToolCall">>) -> 'ToolCall';
fqbin_to_msg_name(<<"hermes.ToolDesc">>) -> 'ToolDesc';
fqbin_to_msg_name(<<"hermes.LLMInferRequest">>) -> 'LLMInferRequest';
fqbin_to_msg_name(<<"hermes.LLMInferResponse">>) -> 'LLMInferResponse';
fqbin_to_msg_name(<<"hermes.ToolExecRequest">>) -> 'ToolExecRequest';
fqbin_to_msg_name(<<"hermes.ToolExecResponse">>) -> 'ToolExecResponse';
fqbin_to_msg_name(<<"hermes.AgentRequest">>) -> 'AgentRequest';
fqbin_to_msg_name(<<"hermes.AgentResponse">>) -> 'AgentResponse';
fqbin_to_msg_name(E) -> error({gpb_error, {badmsg, E}}).


msg_name_to_fqbin('Message') -> <<"hermes.Message">>;
msg_name_to_fqbin('ToolCall') -> <<"hermes.ToolCall">>;
msg_name_to_fqbin('ToolDesc') -> <<"hermes.ToolDesc">>;
msg_name_to_fqbin('LLMInferRequest') -> <<"hermes.LLMInferRequest">>;
msg_name_to_fqbin('LLMInferResponse') -> <<"hermes.LLMInferResponse">>;
msg_name_to_fqbin('ToolExecRequest') -> <<"hermes.ToolExecRequest">>;
msg_name_to_fqbin('ToolExecResponse') -> <<"hermes.ToolExecResponse">>;
msg_name_to_fqbin('AgentRequest') -> <<"hermes.AgentRequest">>;
msg_name_to_fqbin('AgentResponse') -> <<"hermes.AgentResponse">>;
msg_name_to_fqbin(E) -> error({gpb_error, {badmsg, E}}).


-spec fqbin_to_enum_name(_) -> no_return().
fqbin_to_enum_name(E) -> error({gpb_error, {badenum, E}}).


-spec enum_name_to_fqbin(_) -> no_return().
enum_name_to_fqbin(E) -> error({gpb_error, {badenum, E}}).


get_package_name() -> hermes.


%% Whether or not the message names
%% are prepended with package name or not.
uses_packages() -> false.


source_basename() -> "hermes.proto".


%% Retrieve all proto file names, also imported ones.
%% The order is top-down. The first element is always the main
%% source file. The files are returned with extension,
%% see get_all_proto_names/0 for a version that returns
%% the basenames sans extension
get_all_source_basenames() -> ["hermes.proto"].


%% Retrieve all proto file names, also imported ones.
%% The order is top-down. The first element is always the main
%% source file. The files are returned sans .proto extension,
%% to make it easier to use them with the various get_xyz_containment
%% functions.
get_all_proto_names() -> ["hermes"].


get_msg_containment("hermes") -> ['AgentRequest', 'AgentResponse', 'LLMInferRequest', 'LLMInferResponse', 'Message', 'ToolCall', 'ToolDesc', 'ToolExecRequest', 'ToolExecResponse'];
get_msg_containment(P) -> error({gpb_error, {badproto, P}}).


get_pkg_containment("hermes") -> undefined;
get_pkg_containment(P) -> error({gpb_error, {badproto, P}}).


get_service_containment("hermes") -> [];
